// Drives a capture session over CDP with trusted mouse clicks.
// usage: node .capture-drive.mjs <debuggingUrl> <targetId> <selector-or-text>...
import WebSocket from './node_modules/@inkly-org/interactive-demo-cli/node_modules/ws/wrapper.mjs';

const [debugUrl, targetId, ...clicks] = process.argv.slice(2);
const list = await (await fetch(`${debugUrl}/json/list`)).json();
const target = list.find((t) => t.id === targetId);
if (!target) throw new Error('target not found');
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((r) => ws.once('open', r));
let id = 0;
const pending = new Map();
ws.on('message', (m) => {
  const msg = JSON.parse(m);
  if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
});
const send = (method, params = {}) => new Promise((res, rej) => {
  const i = ++id;
  pending.set(i, (msg) => (msg.error ? rej(new Error(JSON.stringify(msg.error))) : res(msg.result)));
  ws.send(JSON.stringify({ id: i, method, params }));
});
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

for (const spec of clicks) {
  // spec: "text:<button text>" or a CSS selector
  const expr = spec.startsWith('text:')
    ? `(() => { const t = ${JSON.stringify(spec.slice(5))}; const el = [...document.querySelectorAll('a,button')].find(e => e.textContent.trim() === t && e.offsetParent !== null); if (!el) return null; el.scrollIntoView({block:'nearest'}); const r = el.getBoundingClientRect(); return {x: r.x + r.width/2, y: r.y + r.height/2, url: location.href}; })()`
    : `(() => { const el = document.querySelector(${JSON.stringify(spec)}); if (!el) return null; el.scrollIntoView({block:'nearest'}); const r = el.getBoundingClientRect(); return {x: r.x + r.width/2, y: r.y + r.height/2, url: location.href}; })()`;
  let pt = null;
  for (let tries = 0; tries < 20 && !pt; tries++) {
    const res = await send('Runtime.evaluate', { expression: expr, returnByValue: true });
    pt = res.result.value;
    if (!pt) await sleep(250);
  }
  if (!pt) throw new Error(`could not find ${spec}`);
  console.log(`click ${spec} at ${Math.round(pt.x)},${Math.round(pt.y)} on ${pt.url}`);
  await send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: pt.x, y: pt.y });
  await sleep(150);
  await send('Input.dispatchMouseEvent', { type: 'mousePressed', x: pt.x, y: pt.y, button: 'left', clickCount: 1 });
  await send('Input.dispatchMouseEvent', { type: 'mouseReleased', x: pt.x, y: pt.y, button: 'left', clickCount: 1 });
  await sleep(2500);
}
ws.close();
